update public.products set description='Fresh tiger nuts are small edible tubers with a naturally sweet, nutty flavour and chewy texture, suitable for eating after thorough cleaning or for preparing Kunu Aya, smoothies and other foods.', handling_protocols=array['Sort carefully and remove damaged, discoloured, moldy or unusually soft tiger nuts together with stones and soil.','Wash thoroughly under clean running water before eating, soaking or processing.','If soaking for an extended period, use potable water and refrigerate rather than leaving the nuts for many hours in warm conditions.','When making tiger-nut milk, use clean water, utensils and containers and refrigerate the finished drink immediately.']::text[], storage_tips=array['Refrigerate fresh tiger nuts promptly and avoid trapping free water or condensation around them.','For best fresh quality, use within about 3–5 days after delivery.','Once soaked or rehydrated, refrigerate and use within about 1–2 days.','Homemade tiger-nut milk should be refrigerated immediately and preferably consumed within about 1–2 days.']::text[] where name='Tiger Nuts' and category_id=(select id from public.product_categories where name='Tubers & Legumes');
update public.products set description='Dried tiger nuts have much of their natural moisture removed, giving them a firmer, chewier texture and longer keeping quality than fresh tiger nuts; they can be eaten after cleaning, soaked to soften, or processed into milk or flour.', handling_protocols=array['Keep clean and dry and inspect before use for mold, insects, damaged tubers or foreign material.','Wash thoroughly under clean running water before eating or processing.','If soaking to soften, use clean potable water; once rehydrated, treat the nuts as a perishable high-moisture food.']::text[], storage_tips=array['Store in a clean airtight or moisture-resistant container in a cool, dry and dark location.','Ensure the nuts are completely dry before resealing the container.','For best quality, use within about 2–3 months when stored airtight and dry.','After soaking, refrigerate and use within about 1–2 days; discard if moldy, musty, insect-infested or sour-smelling.']::text[] where name='Tiger Nut (Dried)' and category_id=(select id from public.product_categories where name='Tubers & Legumes');;
